// ---- HTTP HELPER ----
function httpReq(urlStr, opts, body) {
  return new Promise((resolve, reject) => {
    const u = new URL(urlStr);
    const mod = u.protocol === 'https:' ? https : http;
    const reqOpts = {
      hostname: u.hostname, port: u.port || (u.protocol === 'https:' ? 443 : 80),
      path: u.pathname + u.search, method: opts.method || 'GET',
      headers: opts.headers || {}, timeout: opts.timeout || 30000
    };
    const req = mod.request(reqOpts, (res) => {
      let data = '';
      res.on('data', c => data += c);
      res.on('end', () => {
        try { resolve(JSON.parse(data)); } catch { resolve({ _raw: data, _status: res.statusCode }); }
      });
    });
    req.on('error', e => reject(e));
    req.on('timeout', () => { req.destroy(); reject(new Error('Timeout')); });
    if (body) req.write(typeof body === 'string' ? body : JSON.stringify(body));
    req.end();
  });
}

async function post(url, headers, body, timeout) {
  return httpReq(url, { method: 'POST', headers: { 'Content-Type': 'application/json', ...headers }, timeout: timeout || 30000 }, body);
}
async function get(url, headers) {
  return httpReq(url, { method: 'GET', headers: headers || {} });
}
async function patch(url, headers, body) {
  return new Promise((resolve, reject) => {
    const u = new (require('url').URL)(url);
    const opts = { hostname: u.hostname, port: u.port || 80, path: u.pathname + u.search, method: 'PATCH', headers: { ...headers, 'Content-Type': 'application/json' } };
    const req = require('http').request(opts, (res) => { let d = ''; res.on('data', c => d += c); res.on('end', () => { try { resolve(JSON.parse(d)); } catch { resolve(d); } }); });
    req.on('error', reject);
    if (body) req.write(JSON.stringify(body));
    req.end();
  });
}
async function put(url, headers, body) {
  return httpReq(url, { method: 'PUT', headers: { 'Content-Type': 'application/json', ...headers } }, body);
}

// --- Load prompt from DB ---
async function loadPrompt(key) {
  return new Promise((resolve) => {
    const req = http.get(
      'http://127.0.0.1:5678/webhook/prompt-server?key=' + encodeURIComponent(key),
      res => {
        let data = '';
        res.on('data', c => data += c);
        res.on('end', () => {
          try { const p = JSON.parse(data); resolve(p.success ? p.content : null); }
          catch { resolve(null); }
        });
      }
    );
    req.on('error', () => resolve(null));
    req.setTimeout(5000, () => { req.destroy(); resolve(null); });
  });
}

