// ---- TOOL EXECUTORS ----

async function callLLM(msgs, toolChoice) {
  const body = { model: chatModel, messages: msgs, max_tokens: 4096, temperature: 0.7 };
  if (toolChoice !== 'none') { body.tools = tools; body.tool_choice = toolChoice || 'auto'; }
  return post('http://litellm:4000/v1/chat/completions', { 'Authorization': 'Bearer ' + litellmKey }, body, 120000);
}

async function outlineAPI(endpoint, body) {
  return post('http://outline:3000/api/' + endpoint, { 'Authorization': 'Bearer ' + outlineKey }, body);
}

async function planeGET(path) {
  return get('http://proxy:80/api/v1/workspaces/' + planeSlug + '/' + path, { 'X-API-Key': planeKey });
}
async function planePOST(path, body) {
  return post('http://proxy:80/api/v1/workspaces/' + planeSlug + '/' + path, { 'X-API-Key': planeKey }, body);
}
async function planePATCH(path, body) {
  return patch('http://proxy:80/api/v1/workspaces/' + planeSlug + '/' + path, { 'X-API-Key': planeKey }, body);
}

async function embedText(text) {
  const resp = await post('http://litellm:4000/v1/embeddings', { 'Authorization': 'Bearer ' + litellmKey }, { model: 'mistral-embed', input: [text.substring(0, 8000)] });
  return resp.data && resp.data[0] ? resp.data[0].embedding : null;
}

function classifyDomain(url) {
  const d = (url || '').replace('https://', '').replace('http://', '').split('/')[0].toLowerCase();
  const match = (list) => list.some(s => d.indexOf(s) >= 0);
  if (d.indexOf('.gov') >= 0 || d.indexOf('.mil') >= 0) return 'government';
  if (d.indexOf('.edu') >= 0 || d.indexOf('.ac.') >= 0) return 'academic';
  if (match(['arxiv','pubmed','jstor','springer','nature.com','sciencedirect','science.org','doi.org'])) return 'academic_journal';
  if (match(['reuters','apnews','bbc.com','nytimes','washingtonpost','theguardian','economist','ft.com','bloomberg'])) return 'major_news';
  if (match(['techcrunch','wired.com','arstechnica','theverge','zdnet','venturebeat'])) return 'tech_news';
  if (match(['medium.com','substack','wordpress.com','blogspot'])) return 'blog';
  if (d.indexOf('wikipedia.org') >= 0) return 'encyclopedia';
  if (match(['statista','mckinsey','deloitte','gartner','forrester','idc.com','bcg.com','bain.com','pwc.com','accenture'])) return 'consulting_firm';
  return 'general';
}

async function execDeepResearch(args) {
  const goal = args.goal || '';
  const context = args.context || '';
  const constraints = args.constraints || '';
  // 1. Build 3 search queries
  const queries = [
    { q: goal, type: 'direct' },
    { q: goal + ' criticism OR concerns OR problems OR risks', type: 'critical' },
    { q: goal + ' alternative perspective OR different approach', type: 'alternative' }
  ];
  // 2. Run 3 SearXNG searches IN PARALLEL
  let allResults = [];
  const searchResults = await Promise.allSettled(
    queries.map(query => get('http://searxng:8080/search?q=' + encodeURIComponent(query.q) + '&format=json&engines=google,duckduckgo,brave&categories=general', {}))
  );
  for (let i = 0; i < queries.length; i++) {
    if (searchResults[i].status === 'fulfilled') {
      for (const r of (searchResults[i].value.results || [])) {
        allResults.push({ url: r.url, title: r.title || '', snippet: r.content || '', score: r.score || 0, query_type: queries[i].type });
      }
    }
  }
  // 3. Deduplicate by normalized URL, top 8 by score
  const seen = new Set();
  const deduped = [];
  for (const r of allResults.sort((a, b) => b.score - a.score)) {
    const norm = r.url.replace(/\/$/, '').replace(/^https?:\/\//, '').toLowerCase();
    if (!seen.has(norm) && deduped.length < 8) { seen.add(norm); deduped.push(r); }
  }
  if (deduped.length === 0) return JSON.stringify({ summary: 'No search results found for: ' + goal, sources: [] });
  // 4. Fetch pages (top 8) with paywall bypass — IN PARALLEL
  async function fetchPage(r) {
    let content = '', fetchSource = 'direct';
    try {
      const resp = await get('https://r.jina.ai/' + r.url, { 'Accept': 'application/json', 'X-Return-Format': 'text' });
      content = (resp._raw || resp.data?.content || resp.content || '').substring(0, 4000);
    } catch { content = ''; }
    if (content.length < 200) {
      try {
        const archResp = await get('https://r.jina.ai/https://archive.ph/' + r.url, { 'Accept': 'application/json', 'X-Return-Format': 'text' });
        const archContent = (archResp._raw || archResp.data?.content || archResp.content || '').substring(0, 4000);
        if (archContent.length > content.length) { content = archContent; fetchSource = 'archive.ph'; }
      } catch { /* fallback failed */ }
    }
    if (content.length < 200) {
      try {
        const wayResp = await get('https://r.jina.ai/https://web.archive.org/web/' + r.url, { 'Accept': 'application/json', 'X-Return-Format': 'text' });
        const wayContent = (wayResp._raw || wayResp.data?.content || wayResp.content || '').substring(0, 4000);
        if (wayContent.length > content.length) { content = wayContent; fetchSource = 'web.archive.org'; }
      } catch { /* fallback failed */ }
    }
    const domain = classifyDomain(r.url);
    return { url: r.url, title: r.title, domain, source_type: domain, query_type: r.query_type, fetch_source: fetchSource, content: content || r.snippet || '' };
  }
  const fetchResults = await Promise.allSettled(deduped.slice(0, 8).map(r => fetchPage(r)));
  const sources = [], pageContents = [];
  for (const fr of fetchResults) {
    if (fr.status === 'fulfilled') {
      sources.push({ url: fr.value.url, title: fr.value.title, domain: fr.value.domain, source_type: fr.value.source_type, query_type: fr.value.query_type, fetch_source: fr.value.fetch_source });
      pageContents.push(fr.value.content);
    }
  }
  if (sources.length === 0) return JSON.stringify({ summary: 'Could not fetch any pages for: ' + goal, sources: [] });
  // 5. Genealogy L1: citation clustering
  const parent = sources.map((_, i) => i);
  function find(x) { return parent[x] === x ? x : (parent[x] = find(parent[x])); }
  function union(a, b) { parent[find(a)] = find(b); }
  for (let i = 0; i < sources.length; i++) {
    const contentLower = pageContents[i].toLowerCase();
    for (let j = 0; j < sources.length; j++) {
      if (i === j) continue;
      let refUrl = sources[j].url.replace(/^https?:\/\//, '').replace(/\/$/, '').toLowerCase();
      if (refUrl.length > 10 && contentLower.indexOf(refUrl) >= 0) union(i, j);
    }
  }
  const clusters = {};
  for (let i = 0; i < sources.length; i++) { const root = find(i); if (!clusters[root]) clusters[root] = []; clusters[root].push(i); }
  const clusterCount = Object.keys(clusters).length;
  const isCitationMonoculture = clusterCount < 3 && sources.length >= 3;
  // 6. Store vectors in Qdrant research collection — IN PARALLEL
  const storeResults = await Promise.allSettled(sources.map(async (s, i) => {
    if (!pageContents[i] || pageContents[i].length < 50) return false;
    try {
      const vector = await embedText(s.title + ': ' + pageContents[i].substring(0, 2000));
      if (!vector) return false;
      const hex = () => Math.floor(Math.random() * 16).toString(16);
      const qId = [8,4,4,4,12].map(n => Array.from({length: n}, hex).join('')).join('-').replace(/^(.{12})(.)/, '$14').replace(/^(.{17})(.)/, '$1a');
      await put('http://qdrant:6333/collections/research/points', {}, { points: [{ id: qId, vector, payload: { source: 'deep_research', url: s.url, title: s.title, domain_type: s.domain, query_type: s.query_type, content_preview: pageContents[i].substring(0, 500), goal, timestamp: new Date().toISOString() } }] }).catch(() => {});
      return true;
    } catch { return false; }
  }));
  const storedCount = storeResults.filter(r => r.status === 'fulfilled' && r.value).length;
  // 7. Build synthesis prompt with critical framework
  let genealogyNote = '';
  if (isCitationMonoculture) genealogyNote = '\n\nWARNING: Citation monoculture detected \u2014 most sources appear to trace back to few original claims. Flag this in your analysis.';
  let synthPrompt;
  if (loadedDeepResearchPrompt) {
    synthPrompt = loadedDeepResearchPrompt;
    if (isCitationMonoculture) synthPrompt += genealogyNote;
  } else {
    synthPrompt = 'You are a critical research analyst. Produce honest, well-sourced analysis.\n\nBefore analyzing these sources, assess each one:\n- ORIGIN: Who published this? Who funds them? What do they sell or advocate for?\n- TIMING: Why is this published now? What recent event does it follow?\n- BENEFICIARY: Who gains if this narrative is accepted as true?\n- OMISSION: What perspectives, data, or actors are notably absent?\n- CONSENSUS: Are sources independently corroborating, or tracing back to one original claim?\n\nFlag any source where the publisher has a financial or political stake in the conclusion.\nFor any statistic: state who measured it, when, sample size, methodology, who commissioned it.\n\nOUTPUT STRUCTURE (Markdown):\n\n## Established\nHigh-confidence findings with multiple independent sources. Cite by name.\n\n## Claimed\nAsserted but not independently verified. Note who claims it and their incentive.\n\n## Contested\nActive disagreement between sources. Present both sides.\n\n## Hidden\nGaps, omissions, notable silences. What important questions are NOT being asked?\n\n## Who Benefits\nIncentive map: who gains from the dominant narrative?\n\n## Who Is Harmed\nImpact on less visible stakeholders.\n\n## Confidence Assessment\nFor each major claim: Verified / Plausible / Contested / Unverified\n\n## Open Questions\nWhat needs further investigation?\n\n## Sources & Methodology\nFor EACH source, one line: [Title](URL) \u2013 [domain_type] \u2013 WHO publishes this, what they sell/advocate, potential bias or financial stake.\n\nRULES:\n- If evidence is weak, say so. Do not sanitize.\n- Name specific sources. Never write \"according to research\" or \"studies show\".\n- Flag vendor/consulting firm claims about their own market.\n- For round numbers note \"estimated\" unless methodology is given.\n- Quote 1-2 key sentences when they reveal bias or key claims.\n- Keep each section concise. Total under 1500 words.' + genealogyNote;
  }
  const userContent = 'RESEARCH GOAL: ' + goal + (context ? '\nCONTEXT: ' + context : '') + (constraints ? '\nCONSTRAINTS: ' + constraints : '') + '\n\nSOURCES (' + sources.length + ', ' + clusterCount + ' independent clusters):\n' + sources.map((s, i) => '--- Source ' + (i+1) + ': ' + s.title + ' [' + s.source_type + '] ' + s.url + ' ---\n' + pageContents[i].substring(0, 3000)).join('\n\n');
  // 8. Synthesize with critical-analysis model
  const synth = await post('http://litellm:4000/v1/chat/completions', { 'Authorization': 'Bearer ' + litellmKey }, { model: 'critical-analysis', messages: [{ role: 'system', content: synthPrompt }, { role: 'user', content: userContent }], max_tokens: 4000, temperature: 0.3 }, 90000);
  const summary = synth.choices?.[0]?.message?.content || 'Synthesis failed.';
  // Auto-persist: create Outline doc so research survives even if next LLM call fails
  let docId = null;
  let docUrl = null;
  try {
    const docTitle = (goal.length > 80 ? goal.substring(0, 77) + '...' : goal).substring(0, 100);
    const docResp = await outlineAPI('documents.create', {
      title: docTitle,
      text: summary,
      collectionId: 'd66650d8-b912-4083-9cc9-6f727a2a4d90',
      publish: true
    });
    docId = docResp.data?.id || null;
    docUrl = docResp.data?.url || null;
  } catch { /* doc creation failed, research still returned to LLM */ }
  return JSON.stringify({ summary, sources: sources.map(s => ({ title: s.title, url: s.url, domain: s.domain, source_type: s.source_type, query_type: s.query_type })), stored_count: storedCount, citation_clusters: clusterCount, is_citation_monoculture: isCitationMonoculture, outline_doc_id: docId, outline_doc_url: docUrl });
}

async function execSearchWeb(args) {
  const q = encodeURIComponent(args.goal);
  const search = await get('http://searxng:8080/search?q=' + q + '&format=json&engines=google,duckduckgo,brave&categories=general', {});
  const results = (search.results || []).slice(0, 5);
  if (results.length === 0) return JSON.stringify({ summary: 'No results found for: ' + args.goal, sources: [] });
  const pages = [];
  for (const r of results.slice(0, 3)) {
    try {
      const resp = await get('https://r.jina.ai/' + r.url, { 'Accept': 'application/json', 'X-Return-Format': 'text' });
      const content = (resp._raw || resp.data?.content || resp.content || '').substring(0, 3000);
      pages.push({ url: r.url, title: r.title, content });
    } catch { pages.push({ url: r.url, title: r.title, content: r.content || '' }); }
  }
  let synthMsgs;
  if (loadedSearchPrompt) {
    const sourceText = pages.map((p, i) => '--- Source ' + (i+1) + ': ' + p.title + ' ---\n' + p.content).join('\n\n');
    const filledPrompt = loadedSearchPrompt.replace('{{goal}}', args.goal).replace('{{context}}', args.context || '').replace('{{sources}}', sourceText);
    synthMsgs = [{ role: 'user', content: filledPrompt }];
  } else {
    const synthPrompt = 'Synthesize these web sources to answer: ' + args.goal + (args.context ? '\nContext: ' + args.context : '') + '\n\nSources:\n' + pages.map((p, i) => '--- Source ' + (i+1) + ': ' + p.title + ' ---\n' + p.content).join('\n\n') + '\n\nProvide a factual synthesis. Cite sources by number.';
    synthMsgs = [{ role: 'user', content: synthPrompt }];
  }
  const synth = await post('http://litellm:4000/v1/chat/completions', { 'Authorization': 'Bearer ' + litellmKey }, { model: 'fast-summary', messages: synthMsgs, max_tokens: 2048, temperature: 0.3 }, 45000);
  const summary = synth.choices?.[0]?.message?.content || 'Synthesis failed.';
  return JSON.stringify({ summary, sources: results.slice(0, 5).map(r => ({ title: r.title, url: r.url })) });
}

async function execCreateDoc(args) {
  const r = await outlineAPI('documents.create', { title: (args.title || 'Untitled').substring(0, 100), text: args.content || '', collectionId: args.collection || 'a325a8b0-b80d-4f4f-93a4-864820ef1250', publish: true });
  const d = r.data || {};
  return JSON.stringify({ success: true, id: d.id, title: d.title, url: d.url });
}

async function execUpdateDoc(args) {
  const b = { id: args.id };
  if (args.title) b.title = args.title.substring(0, 100);
  if (args.content) b.text = args.content;
  const r = await outlineAPI('documents.update', b);
  return JSON.stringify({ success: true, id: r.data?.id, title: r.data?.title });
}

async function execSearchDocs(args) {
  const b = { query: args.query, limit: args.limit || 5, statusFilter: ['published'] };
  if (args.collection) b.collectionId = args.collection;
  const r = await outlineAPI('documents.search', b);
  const docs = (r.data || []).map(d => ({ id: d.document?.id, title: d.document?.title, snippet: (d.document?.text || '').substring(0, 200), score: d.ranking }));
  return JSON.stringify({ results: docs, count: docs.length });
}

async function execReadDoc(args) {
  const r = await outlineAPI('documents.info', { id: args.id });
  const d = r.data || {};
  return JSON.stringify({ id: d.id, title: d.title, content: d.text, url: d.url });
}

async function execMoveDoc(args) {
  const r = await outlineAPI('documents.move', { id: args.id, parentDocumentId: args.parentDocumentId });
  const d = r.data || {};
  return JSON.stringify({ success: true, id: d.id, title: d.title, parentDocumentId: args.parentDocumentId });
}

async function execCreateTask(args) {
  const body = { name: args.name };
  if (args.description) body.description_html = '<p>' + args.description + '</p>';
  if (args.priority && args.priority !== 'none') body.priority = args.priority;
  const r = await planePOST('projects/' + planeProject + '/work-items/', body);
  return JSON.stringify({ success: true, id: r.id, name: r.name, priority: r.priority || 'none' });
}

async function execUpdateTask(args) {
  const b = {};
  if (args.name) b.name = args.name;
  if (args.description !== undefined) b.description_html = '<p>' + args.description + '</p>';
  if (args.priority) b.priority = args.priority;
  if (args.state) {
    const stateMap = {done:'completed',undone:'unstarted',started:'started',backlog:'backlog',cancelled:'cancelled'};
    const group = stateMap[args.state] || args.state;
    const states = await planeGET('projects/' + planeProject + '/states/');
    const stateList = states.results || [];
    const match = stateList.find(s => s.group === group);
    if (match) b.state = match.id;
  }
  const r = await planePATCH('projects/' + planeProject + '/work-items/' + args.id + '/', b);
  return JSON.stringify({ success: true, id: r.id, name: r.name, priority: r.priority || 'none' });
}

async function execListTasks(args) {
  const limit = args.limit || 20;
  let path = 'projects/' + planeProject + '/work-items/?expand=state&per_page=' + Math.min(limit, 100);
  if (args.state && args.state !== 'all') {
    const stateMap = {done:'completed',undone:'unstarted',started:'started',backlog:'backlog',cancelled:'cancelled'};
    const group = stateMap[args.state] || args.state;
    const states = await planeGET('projects/' + planeProject + '/states/');
    const stateList = states.results || [];
    const matchIds = stateList.filter(s => s.group === group).map(s => s.id);
    if (matchIds.length) path += '&state=' + matchIds.join(',');
  }
  const r = await planeGET(path);
  const items = (r.results || []).slice(0, limit);
  return JSON.stringify({ tasks: items.map(t => ({ id: t.id, name: t.name, priority: t.priority || 'none', state: (t.state_detail || {}).name || '' })), count: items.length });
}

function execCode(args) {
  return JSON.stringify({ success: true, language: args.language || 'javascript', code: (args.code || args.goal || '').substring(0, 500), result: { stdout: '(simulated — sandbox not deployed)', stderr: '', exit_code: 0, _stub: true } });
}

async function execSaveMemory(args) {
  const content = args.content || '';
  const type = args.type || 'fact';
  const importance = args.importance || 5;
  const memId = 'mem_' + Date.now();
  // Generate UUID v4 inline
  const hex = () => Math.floor(Math.random() * 16).toString(16);
  const qdrantId = [8,4,4,4,12].map(n => Array.from({length: n}, hex).join('')).join('-').replace(/^(.{12})(.)/, '$14').replace(/^(.{17})(.)/, '$1a');
  const vector = await embedText(type + ': ' + content);
  if (vector) {
    await put('http://qdrant:6333/collections/knowledge/points', {}, { points: [{ id: qdrantId, vector, payload: { source: 'memory', source_id: memId, content_preview: content.substring(0, 500), title: type + ' memory', type, importance, user_id: String(userId), timestamp: new Date().toISOString() } }] }).catch(() => {});
  }
  // Note: memory stored in Qdrant only (no direct postgres from Task Runner sandbox)
  return JSON.stringify({ success: true, type, content_preview: content.substring(0, 100), importance });
}

async function execSearchMemories(args) {
  const vector = await embedText(args.query);
  if (!vector) return JSON.stringify({ results: [], count: 0, error: 'Embedding failed' });
  const r = await post('http://qdrant:6333/collections/knowledge/points/search', {}, { vector, limit: args.top_k || 5, score_threshold: args.score_threshold || 0.35, with_payload: true });
  const hits = (r.result || []).map(h => ({ content: h.payload?.content_preview, title: h.payload?.title, source: h.payload?.source, score: h.score?.toFixed(3) }));
  return JSON.stringify({ results: hits, count: hits.length });
}

