async function executeTool(name, args) {
  switch (name) {
    case 'search_web': return execSearchWeb(args);
    case 'deep_research': return execDeepResearch(args);
    case 'create_document': return execCreateDoc(args);
    case 'update_document': return execUpdateDoc(args);
    case 'search_documents': return execSearchDocs(args);
    case 'read_document': return execReadDoc(args);
    case 'move_document': return execMoveDoc(args);
    case 'create_task': return execCreateTask(args);
    case 'update_task': return execUpdateTask(args);
    case 'list_tasks': return execListTasks(args);
    case 'execute_code': return execCode(args);
    case 'save_memory': return execSaveMemory(args);
    case 'search_memories': return execSearchMemories(args);
    case 'save_reflection': return execSaveMemory({ ...args, type: 'reflection', importance: args.importance || 6 });
    case 'propose_personality_change': return JSON.stringify({ status: 'noted', change: (args.change || '').substring(0, 200) });
    case 'get_budget_status': return execBudgetStatus();
    case 'list_collections': return execListCollections();
    default: return JSON.stringify({ error: 'Unknown tool: ' + name });
  }
}

// Pre-load prompts from DB (before loop to avoid per-iteration latency)
const [loadedDeepResearchPrompt, loadedSearchPrompt] = await Promise.all([
  loadPrompt('tools:deep-research-synthesis'),
  loadPrompt('tools:search-synthesis')
]);

// ---- MAIN LOOP ----

let totalIn = 0, totalOut = 0, iteration = 0;
let finalText = '';
let allMessages = JSON.parse(JSON.stringify(messages));
const messagesLog = [];

// Inject current date into system prompt for date awareness
const now = new Date();
const dateStr = now.toLocaleDateString('en-US', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric', timeZone: 'Europe/Brussels' });
const timeStr = now.toLocaleTimeString('en-US', { hour: '2-digit', minute: '2-digit', hour12: false, timeZone: 'Europe/Brussels' });
const dateContext = '\nCurrent date and time: ' + dateStr + ', ' + timeStr + ' (Europe/Brussels timezone).';
if (allMessages.length > 0 && allMessages[0].role === 'system') {
  allMessages[0].content += dateContext;
}

for (iteration = 0; iteration < MAX_ITER + 1; iteration++) {
  const toolChoice = iteration < MAX_ITER ? 'auto' : 'none';
  let llmResp;
  try {
    llmResp = await callLLM(allMessages, toolChoice);
    // If LiteLLM returned an error response (no choices), retry once after 2s
    if (!llmResp.choices || !llmResp.choices[0]) {
      const errDetail = llmResp.error?.message || llmResp._raw || JSON.stringify(llmResp).substring(0, 300);
      messagesLog.push({ role: 'system', content: 'LLM error (attempt 1): ' + errDetail });
      await new Promise(r => setTimeout(r, 2000));
      llmResp = await callLLM(allMessages, toolChoice);
    }
  } catch (e) {
    // Network error or timeout — retry once
    messagesLog.push({ role: 'system', content: 'LLM exception (attempt 1): ' + e.message });
    try {
      await new Promise(r => setTimeout(r, 2000));
      llmResp = await callLLM(allMessages, toolChoice);
    } catch (e2) {
      messagesLog.push({ role: 'system', content: 'LLM exception (attempt 2): ' + e2.message });
      finalText = 'Sorry, I encountered a connection error reaching the AI service. Please try again.';
      break;
    }
  }

  if (!llmResp || !llmResp.choices || !llmResp.choices[0]) {
    const errDetail = llmResp ? (llmResp.error?.message || llmResp._raw || JSON.stringify(llmResp).substring(0, 300)) : 'null response';
    messagesLog.push({ role: 'system', content: 'LLM error (final): ' + errDetail });
    finalText = 'Sorry, the AI service returned an error. Please try again in a moment.';
    break;
  }

  const msg = llmResp.choices[0].message;
  const tokIn = llmResp.usage?.prompt_tokens || 0;
  const tokOut = llmResp.usage?.completion_tokens || 0;
  totalIn += tokIn;
  totalOut += tokOut;

  messagesLog.push({ role: 'assistant', content: msg.content || null, tool_calls: msg.tool_calls || null, model: llmResp.model || chatModel, tokens_in: tokIn, tokens_out: tokOut });

  const assistantMsg = { role: 'assistant' };
  if (msg.content) assistantMsg.content = msg.content;
  if (msg.tool_calls) assistantMsg.tool_calls = msg.tool_calls;
  allMessages.push(assistantMsg);

  if (!msg.tool_calls || msg.tool_calls.length === 0) {
    finalText = msg.content || '';
    break;
  }

  // Process ALL tool calls in this response (not just the first)
  for (const tc of msg.tool_calls) {
    const toolName = tc.function?.name || 'unknown';
    let toolArgs = {};
    try { toolArgs = JSON.parse(tc.function?.arguments || '{}'); } catch { toolArgs = {}; }
    let toolResult;
    try { toolResult = await executeTool(toolName, toolArgs); }
    catch (e) { toolResult = JSON.stringify({ error: 'Tool execution failed' }); }
    messagesLog.push({ role: 'tool', content: toolResult, tool_call_id: tc.id });
    allMessages.push({ role: 'tool', tool_call_id: tc.id, content: toolResult });
  }
}

if (!finalText && iteration >= MAX_ITER) {
  finalText = 'I used all available tool calls. Here is what I found so far.';
}

return [{ json: {
  final_text: finalText, chat_id: chatId, session_id: sessionId, user_id: userId,
  total_tokens_in: totalIn, total_tokens_out: totalOut, messages_log: messagesLog,
  all_messages: allMessages, model: chatModel
}}];
